import { USERS, expect, test, uniqueName } from "../../fixtures";

test.describe("Manage vendors", () => {
  test("the same vendor name is allowed in a different tenant", { tag: "@VEN-04" }, async ({ apiAs }) => {
    // Arrange: a vendor with the same name already exists in another tenant.
    // A unique suffix keeps reruns against the shared database from colliding within a tenant.
    const name = uniqueName("Acme Freight");
    const globex = await apiAs("otherTenant");
    const setup = await globex.post("/api/vendors", {
      data: { name, category: "logistics", contact_email: "ops@globex-procurement.example" },
    });
    expect(setup.status(), await setup.text()).toBe(201);
    const globexVendor = await setup.json();

    // Act: the signed-in Northwind member creates a vendor with that name.
    const member = await apiAs("member");
    const res = await member.post("/api/vendors", {
      data: { name, category: "logistics", contact_email: "ops@acmefreight.example" },
    });

    // Assert
    expect(res.status(), await res.text()).toBe(201);
    const created = await res.json();
    expect(created.name).toBe(name);
    expect(created.category).toBe("logistics");
    expect(created.id).not.toBe(globexVendor.id);
    expect(USERS.member).toBeTruthy();
  });
});
